package com.example.library.loan;

import java.time.Instant;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class LoanService {
    static final int MAX_ACTIVE_LOANS = 3;

    private final LoanRepository loans;

    public LoanService(LoanRepository loans) {
        this.loans = loans;
    }

    @Transactional
    public Loan borrow(String memberId, String isbn) {
        loans.lockMember(memberId);
        if (loans.countByMemberIdAndReturnedAtIsNull(memberId) >= MAX_ACTIVE_LOANS) {
            throw new LoanLimitExceededException(memberId);
        }
        if (loans.existsByIsbnAndReturnedAtIsNull(isbn)) {
            throw new BookAlreadyOnLoanException(isbn);
        }
        try {
            return loans.saveAndFlush(new Loan(memberId, isbn, Instant.now()));
        } catch (DataIntegrityViolationException e) {
            // another member won the race for the same book (partial unique index)
            throw new BookAlreadyOnLoanException(isbn);
        }
    }
}
